// Normalize both triggers before reading Drive or calling the model.
const incoming = $input.first().json;
const message = incoming.message;
const isTelegram = message?.chat?.id !== undefined;
if (isTelegram && message.from?.is_bot) return [];

const source = isTelegram ? 'telegram' : 'chat';
const chatId = isTelegram ? String(message.chat.id) : '';
const threadId = isTelegram ? (message.message_thread_id ?? null) : null;
const senderId = isTelegram ? String(message.from?.id ?? chatId) : '';
const chatInput = String(isTelegram
  ? (message.text ?? message.caption ?? '')
  : (incoming.chatInput ?? '')).trim();
const sessionId = isTelegram
  ? `telegram:${chatId}:${threadId ?? 0}:${senderId}`
  : `chat:${String(incoming.sessionId ?? $execution.id)}`;
const command = (chatInput.match(/^\/([a-z]+)(?:@\w+)?(?:\s|$)/i)?.[1] ?? '').toLowerCase();

// Recognize complete, unfiltered library-count questions before calling the model.
// Anchored patterns deliberately leave artist, format and other filtered counts to the agent.
const question = chatInput
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
  .replace(/^(?:bonjour|bonsoir|salut)\s+/, '')
  .replace(/^(?:(?:est ce que )?tu peux|peux tu|pourrais tu)\s+(?:me\s+)?/, '')
  .replace(/^(?:dire|donner|indiquer|dis moi|donne moi|indique moi|affiche(?: moi)?)\s+/, '')
  .replace(/^(?:au total|en tout)\s+/, '')
  .replace(/\s+(?:s il te plait|s il vous plait|svp|stp|merci)$/, '')
  .trim();
const musicNoun = '(?:musiques?|chansons?|morceaux?|titres?|fichiers? (?:audios?|musicaux))';
const ownership = '(?:ai je|j ai|je possede|que j ai|que je possede|est ce que j ai|est ce que je possede)';
const libraryPlace = '(?:dans (?:ma|la) (?:bibliotheque|collection)(?: musicale| de musiques?)?'
  + '|dans (?:mon|le) dossier(?: (?:de )?musiques?)?'
  + '|sur (?:mon |le )?(?:google )?drive)';
const scope = `(?: (?:au total|en tout))?(?: ${libraryPlace})?(?: (?:au total|en tout))?`;
const countPatterns = [
  `(?:j ai|je possede) combien de ${musicNoun}`,
  `combien de ${musicNoun}(?: ${ownership})?`,
  `combien ${ownership} de ${musicNoun}`,
  `combien (?:y a t il|il y a) de ${musicNoun}`,
  `il y a combien de ${musicNoun}`,
  `(?:quel est |c est quoi )?(?:le |mon )?(?:nombre(?: total)?|total) (?:de |de mes |des )${musicNoun}(?: ${ownership})?`,
  `(?:compte|compter|denombre|denombrer) (?:mes|les|(?:tous|toutes) (?:mes|les)) ${musicNoun}(?: ${ownership})?`,
  '(?:quel est |c est quoi )?(?:le |mon )?(?:nombre total de fichiers audio|total) de (?:ma|la) (?:bibliotheque|collection)(?: musicale)?',
];
const countRequested = command === 'total'
  || (!command && countPatterns.some(pattern => new RegExp(`^(?:${pattern})${scope}$`).test(question)));

let output = '';
if (command === 'start' || command === 'help') {
  output = 'Je peux rechercher dans ta bibliothèque Google Drive et te conseiller des musiques.\n\n'
    + 'Exemples :\n'
    + '• Propose-moi 5 titres que je possède.\n'
    + '• Quelles musiques de The Weeknd ai-je ?\n'
    + '• Conseille-moi 5 morceaux non retrouvés dans ma bibliothèque.\n'
    + '• J’ai combien de musiques ? (ou /total) : compter tous mes fichiers audio.';
} else if (!chatInput) {
  output = 'Envoie-moi un message écrit pour rechercher ou découvrir des musiques. '
    + 'Les messages vocaux ne sont pas transcrits dans ce workflow.';
}

return [{ json: {
  source, chatId, threadId, sessionId, chatInput, command, countRequested,
  needsProcessing: !output, output,
} }];

// Count /total and recognized library-count questions without sending the inventory to the model.
const rows = $input.all().map(item => item.json);
if (rows.some(row => row.error !== undefined && row.error !== null)) {
  return [{ json: {
    output: 'Je n’ai pas pu compter les fichiers Google Drive. '
      + 'Vérifie le compte et le dossier du nœud Google Drive - Count files, '
      + 'puis consulte cette exécution n8n pour le détail de l’erreur.',
  } }];
}

const ids = new Set();
for (const row of rows) {
  if (typeof row.id !== 'string' || typeof row.name !== 'string' || row.trashed) continue;
  if (!String(row.mimeType ?? '').startsWith('audio/')) continue;
  ids.add(row.id);
}
const total = ids.size;
const output = total
  ? `Ta bibliothèque contient ${total.toLocaleString('fr-FR')} fichiers audio.\n`
    + 'Ce total compte les fichiers audio directement dans le dossier sélectionné ; deux copies d’un morceau comptent pour deux fichiers.'
  : 'Aucun fichier identifié comme audio par Google Drive n’est visible dans le dossier configuré. '
    + 'Vérifie le dossier, les autorisations du compte n8n et le type des fichiers.';
return [{ json: { output, total_fichiers_audio: total } }];

