={{ (() => {
  const search = $fromAI('recherche', 'Un artiste ou des mots importants du titre, huit mots maximum. Ne pas envoyer une phrase de conversation. Une chaîne vide donne un aperçu limité de la bibliothèque.', 'string', '');
  const words = String(search ?? '').normalize('NFC').match(/[\p{L}\p{N}]+/gu) ?? [];
  const clauses = words.slice(0, 8).map(word => `(name contains '${word}' or fullText contains '${word}')`);
  return ["(mimeType contains 'audio/')", ...clauses].join(' and ');
})() }}

