const request = $('Prepare request').first().json;
const result = $input.first().json;
let output = typeof result.output === 'string' ? result.output.trim() : '';
if (result.error || !output || /agent stopped due to (?:max|iteration)/i.test(output)) {
  output = 'Je n’ai pas pu terminer la réponse avec le modèle. '
    + 'Vérifie AI Agent, Google Drive Tool et la connexion Ollama dans cette exécution n8n. '
    + 'Tu peux tester /total pour vérifier Google Drive sans appeler le modèle.';
}
return [{ json: { source: request.source, chatId: request.chatId, threadId: request.threadId, output } }];

// Split before escaping HTML; never split a UTF-16 surrogate pair.
const input = $input.first().json;
let remaining = String(input.output ?? '').trim();
if (!remaining || !input.chatId) throw new Error('Missing Telegram message or destination.');
const chunks = [];
const maxLength = 3500;
while (remaining.length > maxLength) {
  let cut = maxLength;
  const newline = remaining.lastIndexOf('\n', cut);
  const space = remaining.lastIndexOf(' ', cut);
  if (newline > maxLength / 2) cut = newline;
  else if (space > maxLength / 2) cut = space;
  const previous = remaining.charCodeAt(cut - 1);
  if (previous >= 0xD800 && previous <= 0xDBFF) cut--;
  chunks.push(remaining.slice(0, cut));
  remaining = remaining.slice(cut);
}
if (remaining) chunks.push(remaining);
const escapeHtml = text => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return chunks.map((chunk, index) => ({
  json: {
    chatId: input.chatId, threadId: input.threadId,
    text: escapeHtml(chunks.length > 1 ? `(${index + 1}/${chunks.length})\n${chunk}` : chunk),
  },
  pairedItem: { item: 0 },
}));
